"""matplotlib.backends.backend_svg — svg backend stub.

The shim renders every figure through plotly, so this module exists to
satisfy ``from matplotlib.backends.backend_svg import
FigureCanvasSVG`` imports. Saving uses plotly's native export.
"""

from matplotlib.backends._backend_helpers import (
    _make_canvas, _make_manager, _make_backend,
)


FigureCanvasSVG = _make_canvas('FigureCanvasSVG', 'svg')
FigureManagerSVG = _make_manager('FigureManagerSVG')

# Aliases — every backend exposes ``FigureCanvas`` and ``FigureManager``.
FigureCanvas = FigureCanvasSVG
FigureManager = FigureManagerSVG

# Backend class registered with matplotlib's _Backend system.
_BackendStub = _make_backend('_BackendSVG', FigureCanvas, FigureManager)
new_figure_manager = _BackendStub.new_figure_manager
draw_if_interactive = _BackendStub.draw_if_interactive
show = _BackendStub.show


# ─── Real implementations for the SVG backend ──────────────────


from matplotlib.backend_bases import RendererBase


class XMLWriter:
    """Buffered SVG element writer. Mirrors upstream's
    ``matplotlib.backends.backend_svg.XMLWriter`` surface — start/end
    a tag, emit attributes, push text, close everything cleanly."""

    def __init__(self, file=None):
        self._file = file
        self._tags = []          # open-tag stack
        self._open = False       # is the current tag still accepting attrs?
        self._buf = []

    def _write(self, s):
        if self._file is not None and hasattr(self._file, 'write'):
            self._file.write(s)
        else:
            self._buf.append(s)

    def getvalue(self):
        """Return the buffered XML when no file was passed."""
        return ''.join(self._buf)

    def _close_open(self):
        if self._open:
            self._write('>')
            self._open = False

    def start(self, tag, attrib=None, **extra):
        """Open an XML element; subsequent calls to ``element`` /
        ``end`` may add children."""
        self._close_open()
        attrib = dict(attrib) if attrib else {}
        attrib.update(extra)
        attrs = ''.join(f' {k}="{_escape_attr(v)}"' for k, v in attrib.items()
                         if v is not None)
        self._write(f'<{tag}{attrs}')
        self._tags.append(tag)
        self._open = True

    def end(self, indent=True, tag=None):
        if not self._tags:
            return
        opened = self._tags.pop()
        if tag is not None and tag != opened:
            # mismatched close — preserve upstream's tolerant behaviour
            pass
        if self._open:
            self._write(' />')
            self._open = False
        else:
            self._write(f'</{opened}>')
            if indent:
                self._write('\n')

    def data(self, text):
        """Insert a text node inside the current element."""
        self._close_open()
        self._write(_escape_text(text))

    def comment(self, comment):
        self._close_open()
        self._write(f'<!-- {_escape_text(comment)} -->\n')

    def element(self, tag, text=None, attrib=None, **extra):
        """Shorthand for ``start + (data) + end``."""
        self.start(tag, attrib, **extra)
        if text is not None:
            self.data(text)
        self.end(indent=False)

    def close(self, tag=None):
        """Close every still-open tag."""
        while self._tags:
            self.end(tag=tag)

    def flush(self):
        if self._file is not None and hasattr(self._file, 'flush'):
            self._file.flush()


def _escape_attr(value):
    """Escape an attribute value for SVG."""
    return (str(value)
            .replace('&', '&amp;')
            .replace('"', '&quot;')
            .replace('<', '&lt;')
            .replace('>', '&gt;'))


def _escape_text(value):
    """Escape a text node for SVG."""
    return (str(value)
            .replace('&', '&amp;')
            .replace('<', '&lt;')
            .replace('>', '&gt;'))


class RendererSVG(RendererBase):
    """SVG renderer — drives an :class:`XMLWriter` to emit SVG markup.
    Inherits the standard GC + text-metrics + draw_* contract; we
    output `<path>`/`<text>`/`<g>` tags into the underlying writer."""

    def __init__(self, width=640, height=480, svgwriter=None, basename=None,
                  image_dpi=72, *, metadata=None):
        super().__init__()
        self.width = float(width)
        self.height = float(height)
        self.image_dpi = float(image_dpi)
        self.basename = basename
        self.metadata = dict(metadata) if metadata else {}
        # Underlying XMLWriter — accept a file-like, a path, or None
        # (in-memory buffer the caller pulls back via .getvalue()).
        if svgwriter is None:
            self.writer = XMLWriter()
        elif hasattr(svgwriter, 'write'):
            self.writer = XMLWriter(svgwriter)
        else:
            self.writer = XMLWriter()
        # Emit the prolog + opening <svg>.
        self.writer._write(svgProlog + '\n')
        # Format dimensions as int when whole, else with up to 4 decimals,
        # so a 100px-wide canvas reads ``width="100"`` not ``width="100.0"``.
        def _fmt(v):
            return f'{int(v)}' if float(v).is_integer() else f'{v:g}'
        self.writer.start('svg', attrib={
            'xmlns': 'http://www.w3.org/2000/svg',
            'width': _fmt(self.width),
            'height': _fmt(self.height),
            'viewBox': f'0 0 {_fmt(self.width)} {_fmt(self.height)}',
        })

    def draw_path(self, gc, path, transform, rgbFace=None):
        """Emit a `<path>` element for the supplied Path."""
        try:
            # Build a tiny `d=` attribute from the path's vertices.
            d_parts = []
            for v in getattr(path, 'vertices', []):
                d_parts.append(f'M {v[0]:g} {v[1]:g}' if not d_parts
                                else f'L {v[0]:g} {v[1]:g}')
            d = ' '.join(d_parts) if d_parts else 'M 0 0'
            stroke = _rgb_to_hex(gc.get_foreground()) if hasattr(gc, 'get_foreground') else '#000'
            fill = _rgb_to_hex(rgbFace) if rgbFace else 'none'
            self.writer.element('path',
                attrib={'d': d, 'stroke': stroke, 'fill': fill,
                         'stroke-width': f'{getattr(gc, "_linewidth", 1):g}'})
        except Exception:
            pass

    def draw_text(self, gc, x, y, s, prop, angle, ismath=False, mtext=None):
        try:
            size = prop.get_size_in_points() if hasattr(prop, 'get_size_in_points') \
                   else getattr(prop, 'get_size', lambda: 12)()
            color = _rgb_to_hex(gc.get_foreground()) if hasattr(gc, 'get_foreground') else '#000'
            attr = {'x': f'{x:g}', 'y': f'{y:g}',
                     'font-size': f'{size}', 'fill': color}
            if angle:
                attr['transform'] = f'rotate({-angle:g} {x:g} {y:g})'
            self.writer.element('text', text=s, attrib=attr)
        except Exception:
            pass

    def finalize(self):
        """Close the root <svg> element + return the SVG text."""
        self.writer.close()
        return self.writer.getvalue()


def _rgb_to_hex(c):
    """Convert (r, g, b[, a]) in [0, 1] to #RRGGBB."""
    try:
        return '#{:02x}{:02x}{:02x}'.format(
            int(max(0, min(255, c[0] * 255))),
            int(max(0, min(255, c[1] * 255))),
            int(max(0, min(255, c[2] * 255))))
    except Exception:
        return '#000000'


svgProlog = '<?xml version="1.0" encoding="utf-8" standalone="no"?>'
